contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint d) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d) + (0)); require(d <= 1000000000000000000000000000000);
        require(address(this).balance >= d);
        c.deposit{value: d}(); if (__ESBMC_reverted()) return;
        c.deposit{value: 0}(); if (__ESBMC_reverted()) return;
        uint bal0 = address(c).balance;
        uint self0 = address(this).balance;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        assert(address(c).balance == bal0 - d && address(this).balance == self0 + d);
    }
    receive() external payable {}
}

