// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 d) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= d);
        try c.deposit{value: d}() {} catch { return; }
        try c.deposit{value: 0}() {} catch { return; }
        uint bal0 = address(c).balance;
        uint self0 = address(this).balance;
        try c.withdrawAll() {} catch { return; }
        assertTrue(address(c).balance == bal0 - d && address(this).balance == self0 + d);
    }

    function testFuzz_run(uint256 d) public {
        _run(d);
    }

    receive() external payable {}
}
